import React, { useState } from 'react';
import { Search } from 'lucide-react';

const MessagesList = () => {
  const [messages] = useState([
    { id: 1, sender: 'John Doe', message: 'Bonjour, j\'ai une question concernant ma commande...', time: '10:30 AM', unread: true },
    { id: 2, sender: 'Sarah Smith', message: 'Merci pour votre aide rapide!', time: 'Hier', unread: false },
    { id: 3, sender: 'Mike Johnson', message: 'Est-ce que le produit sera disponible bientôt?', time: '2 jours', unread: true },
  ]);

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl shadow-lg border border-white/30 dark:border-neutral-800/50">
      <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-neutral-400" />
          </div>
          <input
            type="search"
            placeholder="Rechercher des messages..."
            className="pl-10 pr-4 py-2 w-full rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 transition-all"
          />
        </div>
      </div>
      <div className="max-h-[500px] overflow-y-auto">
        {messages.map((msg) => (
          <div key={msg.id} className={`p-4 border-b border-neutral-100 dark:border-neutral-800/50 hover:bg-neutral-50 dark:hover:bg-neutral-800/30 cursor-pointer transition-colors ${msg.unread ? 'bg-primary-50 dark:bg-primary-900/10' : ''}`}>
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
                <span className="text-white font-medium">{msg.sender.charAt(0)}</span>
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <p className={`font-medium ${msg.unread ? 'text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-300'}`}>{msg.sender}</p>
                  <span className="text-xs text-neutral-500 dark:text-neutral-500">{msg.time}</span>
                </div>
                <p className="text-sm text-neutral-600 dark:text-neutral-400 truncate">{msg.message}</p>
              </div>
              {msg.unread && (
                <span className="h-2 w-2 bg-primary-500 rounded-full"></span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MessagesList;
